function genderPairPlural(masc: string, fem: string, correctIsMasc: boolean): Reasoned {
  const wrong = correctIsMasc ? fem : masc;
  const correct = correctIsMasc ? masc : fem;
  const wrongEnding = correctIsMasc ? '-as' : '-os';
  const correctEnding = correctIsMasc ? '-os' : '-as';
  return { value: wrong, trapType: 'grammar', reason: {
    ru: `${wrong} — форма ${correctIsMasc ? 'женского' : 'мужского'} рода множественного числа, с ${wrongEnding}. ${correctIsMasc ? 'По умолчанию' : 'Для группы женского рода'} нужна форма на ${correctEnding}: ${correct}.`,
    uk: `${wrong} — форма ${correctIsMasc ? 'жіночого' : 'чоловічого'} роду множини, з ${wrongEnding}. ${correctIsMasc ? 'За замовчуванням' : 'Для групи жіночого роду'} потрібна форма на ${correctEnding}: ${correct}.`,
    en: `${wrong} is the ${correctIsMasc ? 'feminine' : 'masculine'} plural form, with ${wrongEnding}. ${correctIsMasc ? 'By default' : 'For a feminine group'}, the form with ${correctEnding} is needed: ${correct}.`,
    'pt-BR': `${wrong} é a forma ${correctIsMasc ? 'feminina' : 'masculina'} plural, com ${wrongEnding}. ${correctIsMasc ? 'Por padrão' : 'Para um grupo feminino'}, precisa da forma com ${correctEnding}: ${correct}.`,
    vi: `${wrong} là dạng ${correctIsMasc ? 'giống cái' : 'giống đực'} số nhiều, với ${wrongEnding}. ${correctIsMasc ? 'Mặc định' : 'Với nhóm giống cái'} cần dạng có ${correctEnding}: ${correct}.`,
    id: `${wrong} adalah bentuk jamak ${correctIsMasc ? 'feminin' : 'maskulin'}, dengan ${wrongEnding}. ${correctIsMasc ? 'Secara default' : 'Untuk kelompok feminin'} perlu bentuk dengan ${correctEnding}: ${correct}.`,
    tr: `${wrong}, ${wrongEnding} ile biten ${correctIsMasc ? 'dişil' : 'eril'} çoğul biçimdir. ${correctIsMasc ? 'Varsayılan olarak' : 'Dişil bir grup için'} ${correctEnding} ile biten biçim gerekir: ${correct}.`,
    pl: `${wrong} to forma ${correctIsMasc ? 'żeńska' : 'męska'} liczby mnogiej, z ${wrongEnding}. ${correctIsMasc ? 'Domyślnie' : 'Dla grupy rodzaju żeńskiego'} potrzebna jest forma na ${correctEnding}: ${correct}.`,
  }};
}

function pluralVsSingularGendered(singular: string, plural: string, aboutOne: string): Reasoned {
  return { value: singular, trapType: 'grammar', reason: {
    ru: `${singular} — форма единственного числа, ${aboutOne}. Про группу нужна форма множественного числа: ${plural}.`,
    uk: `${singular} — форма однини, ${aboutOne}. Про групу потрібна форма множини: ${plural}.`,
    en: `${singular} is the singular form, about one. For a group, the plural form is needed: ${plural}.`,
    'pt-BR': `${singular} é a forma singular, sobre um. Para um grupo, precisa da forma plural: ${plural}.`,
    vi: `${singular} là dạng số ít, về một. Về nhóm cần dạng số nhiều: ${plural}.`,
    id: `${singular} adalah bentuk tunggal, tentang satu. Untuk kelompok perlu bentuk jamak: ${plural}.`,
    tr: `${singular} tekil biçimdir, tek biri hakkındadır. Bir grup için çoğul biçim gerekir: ${plural}.`,
    pl: `${singular} to forma liczby pojedynczej, o jednej osobie. Dla grupy potrzebna jest forma liczby mnogiej: ${plural}.`,
  }};
}

function singularVsPluralGendered(plural: string, singular: string, aboutOne: string): Reasoned {
  return { value: plural, trapType: 'grammar', reason: {
    ru: `${plural} — форма множественного числа, про нескольких. Вопрос про одного — форма единственного числа: ${singular}.`,
    uk: `${plural} — форма множини, про кількох. Питання про одного — форма однини: ${singular}.`,
    en: `${plural} is the plural form, about several. About one, the singular form is needed: ${singular}.`,
    'pt-BR': `${plural} é a forma plural, sobre vários. Sobre um, precisa da forma singular: ${singular}.`,
    vi: `${plural} là dạng số nhiều, về nhiều người. Về một cần dạng số ít: ${singular}.`,
    id: `${plural} adalah bentuk jamak, tentang beberapa. Tentang satu perlu bentuk tunggal: ${singular}.`,
    tr: `${plural} çoğul biçimdir, birden fazlası hakkındadır. Biri hakkında tekil biçim gerekir: ${singular}.`,
    pl: `${plural} to forma liczby mnogiej, o kilku osobach. O jednej potrzebna jest forma liczby pojedynczej: ${singular}.`,
  }};
}

function genderMismatchSingular(correct: string, wrong: string): Reasoned {
  const correctIsMasc = correct.endsWith('o');
  return { value: wrong, trapType: 'grammar', reason: {
    ru: `${wrong} — форма ${correctIsMasc ? 'женского' : 'мужского'} рода. По умолчанию нужна форма на ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
    uk: `${wrong} — форма ${correctIsMasc ? 'жіночого' : 'чоловічого'} роду. За замовчуванням потрібна форма на ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
    en: `${wrong} is the ${correctIsMasc ? 'feminine' : 'masculine'} form. By default, the form with ${correctIsMasc ? '-o' : '-a'} is needed: ${correct}.`,
    'pt-BR': `${wrong} é a forma ${correctIsMasc ? 'feminina' : 'masculina'}. Por padrão, precisa da forma com ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
    vi: `${wrong} là dạng ${correctIsMasc ? 'giống cái' : 'giống đực'}. Mặc định cần dạng có ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
    id: `${wrong} adalah bentuk ${correctIsMasc ? 'feminin' : 'maskulin'}. Secara default perlu bentuk dengan ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
    tr: `${wrong}, ${correctIsMasc ? 'dişil' : 'eril'} biçimdir. Varsayılan olarak ${correctIsMasc ? '-o' : '-a'} ile biten biçim gerekir: ${correct}.`,
    pl: `${wrong} to forma ${correctIsMasc ? 'żeńska' : 'męska'}. Domyślnie potrzebna jest forma na ${correctIsMasc ? '-o' : '-a'}: ${correct}.`,
  }};
}

function wrongWord(correct: string, wrong: string, wrongMeaning: Record<LocaleWithoutEs, string>): Reasoned {
  return { value: wrong, trapType: 'semantic_neighbor', reason: {
    ru: `${wrong} означает ${wrongMeaning.ru} — совсем другой признак. Нужно ${correct}.`,
    uk: `${wrong} означає ${wrongMeaning.uk} — зовсім інша ознака. Потрібно ${correct}.`,
    en: `${wrong} means ${wrongMeaning.en} — a completely different quality. ${correct} is needed.`,
    'pt-BR': `${wrong} significa ${wrongMeaning['pt-BR']} — uma qualidade completamente diferente. Precisa de ${correct}.`,
    vi: `${wrong} nghĩa là ${wrongMeaning.vi} — một đặc điểm hoàn toàn khác. Cần ${correct}.`,
    id: `${wrong} berarti ${wrongMeaning.id} — sifat yang sama sekali berbeda. Perlu ${correct}.`,
    tr: `${wrong}, ${wrongMeaning.tr} demektir — tamamen farklı bir nitelik. ${correct} gerekir.`,
    pl: `${wrong} znaczy ${wrongMeaning.pl} — zupełnie inna cecha. Potrzebne jest ${correct}.`,
  }};
}

